import {readWordFields,updateWordField,createWordField,renameWordField,deleteWordField,wordFieldUsage} from './wordfields.js?v=1.7.2';
import {POEMS,MEDIA,POETOLOGY,filterResources,REEL_WRITING_PROMPTS} from './inspiration.js?v=1.6.2';
import {namedGrammar,decodeLibrary,putGrammar,importGrammar,exportGrammar,unusedImportName} from './library.js?v=1.5.2';
import {GRAMMAR_EXAMPLES} from './examples.js?v=1.6.2';
import {compileGrammar,generateFromGrammar,DEFAULT_RULES,DEFAULT_WORDS} from './grammar.js?v=1.5.2';
import {lessons,validPatterns,analyze,validateSave} from './core.js?v=1.5.2';
const inspirationItems=[...POEMS.map(p=>({...p,type:'Gedichte'})),...MEDIA];
let inspirationFilter={query:'',type:'Alle',theme:'Alle',favoritesOnly:false};
let reelTheme='Alle';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sections=[['ankommen','Clara Lösel','5 MIN'],['lesen','Worte','20 MIN'],['hoeren','Stimme','15 MIN'],['rhythmus','Rhythmus','20 MIN'],['werkstatt','Schreiben','30–45 MIN']];
let state={version:1,done:[],notes:{}},storage=true;try{const old=JSON.parse(localStorage.getItem('zwischen-zeilen-v1'));if(validateSave(old))state=old;}catch{storage=false;}
let pendingWork=null,bookURL=null;
let route='',game=null,lessonIndex=0,soft=true,invert=false,paused=false,ctx=null,ambient=null;
function save(){try{localStorage.setItem('zwischen-zeilen-v1',JSON.stringify(state));}catch{storage=false;toast('Browserspeicher nicht verfügbar. Bitte Lernjournal sichern.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function field(id,label,placeholder=''){return `<label class="field" for="${id}">${label}</label><textarea id="${id}" data-save="${id}" placeholder="${esc(placeholder)}">${esc(state.notes[id]||'')}</textarea>`;}
function head(title,desc){const s=sections.find(x=>x[0]===route);return `<div class="topline"><span>DEINE WORTE · ${s[1].toUpperCase()}</span><span class="pill">IN DEINEM TEMPO</span></div><div class="station-head"><h1>${title}</h1><p class="intro">${desc}</p></div>`;}
function complete(){const i=sections.findIndex(s=>s[0]===route);return `<div class="complete-row"><button class="primary" id="complete">${state.done.includes(route)?'Erledigt ✓':'Fertig'}</button>${i<4?`<a href="#${sections[i+1][0]}">Weiter: ${sections[i+1][1]}</a>`:'<button id="journal-export">Gesamtes Journal exportieren</button>'}<span class="small">Deine Einträge bleiben in diesem Browser.</span></div>`;}
const art=`<div class="art" aria-hidden="true"><svg viewBox="0 0 380 370"><defs><radialGradient id="glow"><stop stop-color="#c5d8ad" stop-opacity=".13"/><stop offset="1" stop-color="#c5d8ad" stop-opacity="0"/></radialGradient></defs><circle cx="190" cy="185" r="185" fill="url(#glow)"/><g fill="none" stroke="#c5d8ad" stroke-width="1.2" opacity=".65"><ellipse cx="190" cy="185" rx="140" ry="142" stroke-dasharray="2 8"/><path d="M65 284Q195 290 300 72M125 260Q96 205 141 178Q148 230 125 260M170 220Q140 157 190 130Q194 181 170 220M216 166Q204 111 246 90Q248 139 216 166M166 224Q225 233 246 190Q196 181 166 224M211 175Q272 184 294 139Q247 135 211 175"/></g><g class="breath"><path d="M99 118Q156 89 193 115L193 283Q148 255 99 274Z" fill="#27352b" stroke="#aabd98"/><path d="M193 115Q246 85 296 110L296 268Q235 251 193 283Z" fill="#202c24" stroke="#aabd98"/><g stroke="#9bab89" opacity=".5"><path d="m115 141 60-3m-60 20 60-3m-60 20 60-3m-60 20 60-3m-60 20 44-3m53-70 65-8m-65 25 65-8m-65 25 65-8m-65 25 65-8m-65 25 45-5"/></g><path d="M191 116v167" stroke="#efa78e"/><path d="m239 110 2 83 13-12 12 9-4-86" fill="#efa78e"/></g><g fill="#efa78e"><circle cx="75" cy="150" r="3"/><circle cx="305" cy="240" r="2"/><path d="m289 60 2-8 2 8 8 2-8 2-2 8-2-8-8-2Z"/></g></svg><span class="orbit-text">hier darf etwas entstehen.</span></div>`;
function landing(){return `<section class="creator-hero"><div class="creator-copy"><p class="eyebrow">LYRIKERIN. POETRY ARTIST. CONTENT CREATORIN.</p><h1>Clara Lösel.<br><em>Das Leben<br>in Zeilen.</em></h1><p class="creator-deck">Clara Lösel schreibt über Liebe, Selbstwert und Gesellschaft. In ihren Gedichten und Videos spricht sie über Erfahrungen, die viele Menschen kennen.</p><p class="creator-description">Clara Lösel bringt Lyrik ins Buch, auf die Bühne und direkt in deinen Feed. Entdecke ihre Texte und Reels – und finde heraus, was du selbst zu sagen hast.</p><div class="actions"><a class="primary" href="#inspiration">Gedichte und Reels ansehen</a><a class="creator-write" href="#werkstatt">Selbst etwas schreiben</a></div><div class="creator-tags"><span>Gedichte</span><span>Original-Reels</span><span>Deine Stimme</span></div></div><figure class="creator-portrait"><img src="assets/clara-loesel-offiziell.jpg" alt="Clara Lösel sitzt mit einem Notizbuch und schreibt." fetchpriority="high"><span class="portrait-sticker">Gedichte beginnen<br>mit einem Gedanken.</span><figcaption>Motiv von <a href="https://claraloesel.de/" target="_blank" rel="noopener noreferrer">claraloesel.de</a> · unabhängiges Inspirationsprojekt</figcaption></figure></section><section class="poetry-invitation" aria-labelledby="invitation-heading"><h2 id="invitation-heading">Was möchtest du schreiben?</h2><a href="#werkstatt">Zur Schreibwerkstatt</a></section><section class="creator-manifest"><p class="eyebrow">WAS SIE MACHT. WAS DU DARAUS MACHST.</p><div><h2>Von der ersten Zeile<br><em>bis in deinen Feed.</em></h2><p>Bei Lösel treffen Alltagsbilder auf grosse Gefühle, Nähe auf Haltung und kurze Formen auf ein öffentliches Publikum. Ein Reel ist dabei auch eine literarische Entscheidung: Stimme, Blick, Pause und Kamera verändern, wie ein Text ankommt.</p><p>Welche Bilder oder Wendungen sprechen dich an? Probiere ein sprachliches Verfahren aus und verändere es für deinen eigenen Text.</p><a href="#inspiration">Gedichte, Podcasts und Porträts entdecken</a></div></section>${reelGallery()}<section class="try-grid"><a class="try-card" href="#lesen"><span>WORTE</span><h2>Eine Zeile.<br>Ein ganzes Gefühl.</h2><p>Entdecke Bilder und Wendungen in Lösels Texten.</p></a><a class="try-card" href="#rhythmus"><span>STIMME</span><h2>Wie klingt<br>dein Gedanke?</h2><p>Spüre Betonung, Pausen und den eigenen Rhythmus.</p></a><a class="try-card" href="#werkstatt"><span>DEIN TEXT</span><h2>Schreibe<br>selbst.</h2><p>Spiele mit Worten und Regeln. Speichere deine eigenen Baupläne.</p></a></section><section class="first-spark"><div><p class="eyebrow">ZUM ANFANG</p><h2>Welches Wort<br>lässt dich gerade<br><em>nicht los?</em></h2><p>Schreibe über eine eigene Erfahrung oder erfinde eine Situation. Ein Gedicht muss daraus noch nicht werden.</p></div><div>${field('start','Was beschäftigt dich gerade?','Notiere einen Gedanken oder eine Beobachtung …')}<a class="primary" href="#werkstatt">Damit weiterschreiben</a></div></section><details class="creator-teacher"><summary>Du nutzt diesen Raum im Unterricht?</summary><p>Die fünf Werkstätten eignen sich für eine Doppelstunde mit Erweiterungen. Unterrichtsplanung, Quellen und Sicherungen sind weiterhin verfügbar. Persönliche Offenheit oder das öffentliche Teilen eigener Texte sind keine Voraussetzung.</p><button id="landing-teacher">Hinweise für Lehrpersonen öffnen</button></details>${complete()}`;}
function visibleReels(){return REEL_WRITING_PROMPTS.filter(reel=>reelTheme==='Alle'||reel.themes.includes(reelTheme));}
function reelTiles(){return visibleReels().map(({id,title,description,prompt,sensitive,themes,example})=>`<article class="reel-tile"><p class="reel-kicker">CLARA LÖSEL / ${themes.join(' · ').toUpperCase()}</p><h3>${esc(title)}</h3><p class="small">${esc(description)}</p>${sensitive?`<p class="content-note">Themenhinweis: ${esc(sensitive)}</p>`:''}<iframe class="original-reel" title="Clara Lösel: ${esc(title)}" src="https://www.instagram.com/p/${id}/embed/" loading="lazy" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><div class="reel-writing"><h4>Schreibidee</h4><p>${esc(prompt)}</p><button class="primary" data-reel-write="${id}" aria-label="Dazu schreiben: ${esc(title)}">Dazu schreiben</button><p class="small">Wörter und Bilder: ${esc(GRAMMAR_EXAMPLES.find(item=>item.id===example).title)}</p><button data-reel-grammar="${id}" aria-label="Mit Wörtern spielen: ${esc(title)}">Mit Wörtern spielen</button></div><a href="https://www.instagram.com/claraloesel/reel/${id}/" target="_blank" rel="noopener noreferrer">Original-Reel öffnen</a></article>`).join('');}
function reelGallery(){return `<section class="reel-gallery" aria-labelledby="reel-heading"><div class="reel-heading"><div><p class="eyebrow">@CLARALOESEL · ORIGINAL-REELS</p><h2 id="reel-heading">Poesie. <em>Mitten im Feed.</em></h2></div><a href="https://www.instagram.com/claraloesel/reels/" target="_blank" rel="noopener noreferrer">Zu Claras Instagram</a></div><p class="reel-intro">Originalbeiträge von @claraloesel zu Liebe, Hoffnung, Selbstwert und Gesellschaft. Die Titel auf dieser Seite beschreiben das jeweilige Thema.</p><div class="tabs reel-filters" role="group" aria-label="Reels nach Thema auswählen">${['Alle','Liebe','Hoffnung','Selbstwert','Gesellschaft'].map(theme=>`<button data-reel-theme="${theme}" aria-pressed="${reelTheme===theme}">${theme}</button>`).join('')}</div><p id="reel-count" class="small" role="status">${visibleReels().length} von ${REEL_WRITING_PROMPTS.length} Reels · Unter jedem Beitrag findest du eine Schreibidee.</p><p class="reel-browse-hint small">Die Galerie lässt sich seitlich durchblättern.</p><div class="reel-feed" id="reel-items">${reelTiles()}</div><p class="small">Die Reels werden direkt von Instagram geladen, sobald sie in die Nähe des sichtbaren Bereichs kommen. Dabei wird eine Verbindung zu Instagram hergestellt. Falls ein Player gesperrt ist oder eine Anmeldung verlangt, öffne das verlinkte Original.</p></section>`;}
function bindReelWriting(){
 const openReel=(id,withGrammar)=>{const reel=REEL_WRITING_PROMPTS.find(item=>item.id===id);state.notes['inspiration-impuls']=`${reel.title} · Clara Lösel\nhttps://www.instagram.com/claraloesel/reel/${reel.id}/\n\n${reel.prompt}`;state.notes['grammar-reel-id']=reel.id;if(withGrammar)state.notes['grammar-example-selected']=reel.example;save();pendingWork=withGrammar?'baukasten':'impuls';location.hash='werkstatt';};
 document.querySelectorAll('[data-reel-write]').forEach(button=>button.onclick=()=>openReel(button.dataset.reelWrite,false));
 document.querySelectorAll('[data-reel-grammar]').forEach(button=>button.onclick=()=>openReel(button.dataset.reelGrammar,true));
}
function bindReelGallery(){bindReelWriting();document.querySelectorAll('[data-reel-theme]').forEach(button=>button.onclick=()=>{reelTheme=button.dataset.reelTheme;document.querySelectorAll('[data-reel-theme]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));$('#reel-items').innerHTML=reelTiles();$('#reel-count').textContent=`${visibleReels().length} von ${REEL_WRITING_PROMPTS.length} Reels · Unter jedem Beitrag findest du eine Schreibidee.`;bindReelWriting();});}
function reading(){return head('Worte, die <em>etwas tragen.</em>','Lies zuerst leise, dann laut. Klicke die markierten Stellen an: Welche Arbeit leisten die Wörter – und was macht der Zeilenbruch?')+`<div class="two-col"><article class="poem"><p class="eyebrow">CLARA LÖSEL · INTRO ZWEI.</p><div class="poem-text">ich weiß, dass ich noch
längst nicht fertig bin mit <button class="annotation" data-annotation="heilen">heilen.</button>
ich wickel <button class="annotation" data-annotation="tesa">tesa um meine tränen</button>
und <button class="annotation" data-annotation="zeilen">verpacke sie in zeilen.</button></div><p class="poem-meta">Clara Lösel: Wehe du gibst auf, „intro zwei.“<br>PDF-Seite 15 (Seitenzählung der bereitgestellten Datei).</p><div class="feedback" id="annotation-feedback" aria-live="polite">Welche Stelle bleibt bei dir hängen?</div></article><div><h2>Vom Gefühl zum Gegenstand.</h2><p class="intro">Der Text macht einen inneren Vorgang mit Dingen aus dem Alltag vorstellbar. Das lyrische Ich ist eine Sprechinstanz; es ist nicht automatisch mit der Autorin gleichzusetzen.</p>${field('deutung','Deine Deutung: sprachlicher Befund → Wirkung → mögliche Bedeutung','Was verbindet das Klebeband mit dem Schreiben? Was bleibt an dem Bild widersprüchlich?')}${field('bruch','Experiment: Verschiebe einen Zeilenbruch. Was ändert sich beim Lesen?','Zum Beispiel nach „fertig“. Beschreibe Erwartung, Pause und Anschluss.')}<button id="reading-hint">Denkhilfe öffnen</button></div></div><article class="card"><h3>Zweite Lektüre im Buch</h3><p><a href="#inspiration">Zur Gedicht- und Medienbibliothek</a></p><p>Lies „lange version.“ (1/101, PDF-Seite 17). Untersuche die wiederkehrende Anrede, den Gegensatz zwischen kurzer und ausführlicher Antwort und die Wirkung der isolierten Antwort. Vergleiche die Nähe zum Gegenüber mit dem Selbstgespräch in „intro zwei.“.</p>${field('vergleich','Vergleich mit Textbelegen und Seitenangabe','Nenne eine Gemeinsamkeit und einen Unterschied. Zitiere nur die jeweils nötige Stelle.')}</article>${complete()}`;}
function hearing(){return head('Ein Text. <em>Viele Stimmen.</em>','Wie verändern Stimme, Blick und Plattform ein Gedicht? Wähle einen frei erreichbaren Beitrag. Du brauchst kein Konto, um die Beobachtungsaufgabe auch mit einem eigenen Vortrag zu lösen.')+`<div class="cards"><article class="card"><span class="icon">◉</span><h3>Auf der Seite</h3><p>Lies einen Text im Buch oder eine kurze Stelle hier im Labor. Markiere gedachte Pausen.</p><a href="https://claraloesel.de/" target="_blank" rel="noopener noreferrer">Lösels Website öffnen</a></article><article class="card"><span class="icon">▤</span><h3>Vor der Kamera</h3><p>Wähle einen zugänglichen Poetry-Beitrag. Achte auf Blick, Schnitt, Gestik und Untertitel.</p><a href="https://www.instagram.com/claraloesel/" target="_blank" rel="noopener noreferrer">Instagram öffnen</a></article><article class="card"><span class="icon">◌</span><h3>Nur die Stimme</h3><p>Suche einen von Lösel gesprochenen Text. Achte auf Atem, Lautstärke und Tempo.</p><a href="https://open.spotify.com/search/clara%20l%C3%B6sel" target="_blank" rel="noopener noreferrer">Auf Spotify suchen</a></article></div><p class="small" style="margin-top:16px">Externe Angebote können eine Anmeldung erfordern. Es wird nichts automatisch eingebettet oder abgespielt. Wenn derselbe Text nicht verfügbar ist, vergleiche zwei eigene Vorträge derselben Stelle.</p><div class="two-col"><div>${field('quelle','Welcher Text / Beitrag? Titel, URL und Zeitstelle','Dokumentiere auch, ob du denselben Text oder unterschiedliche Texte vergleichst.')}${field('hoeren','Beobachtung: Was hörst oder siehst du genau?','Zum Beispiel: hörbare Pause nach …; Blick in die Kamera bei …; betontes Wort …')}</div><div>${field('wirkung','Deutung: Wie verändert sich die Wirkung gegenüber dem stillen Lesen?','Trenne Beobachtung und Interpretation. Was könnte auch anders erklärt werden?')}${field('medium','Plattform: Was fördert Nähe, was lenkt ab?','Unterscheide Stimme/Text von Musik, Untertiteln, Kommentarspalte und Plattformgestaltung.')}</div></div><div class="card"><h3>Stimmenexperiment zu zweit</h3><p><a href="#inspiration">Konkrete Filme, Podcasts und Porträts auswählen</a></p><p>Lest dieselben zwei Zeilen einmal tröstend, einmal fordernd. Welche Wörter ändern ihr Gewicht? Begründet, welche Lesart der Wortlaut stützt. Ohne Originalaufnahme ist das eine vollwertige Alternative.</p></div>${complete()}`;}
function rhythm(){return head('Lies mit <em>den Fingern.</em>','Du bestimmst das Tempo. Pro Silbe entscheidest du: unbetont oder betont. Die Übungsverse sind eigens geschrieben; Lösels freie Verse werden nicht in ein starres Metrum gepresst.')+`<div class="tabs" role="group" aria-label="Rhythmusübungen">${lessons.map((l,i)=>`<button data-lesson="${i}" class="${i===lessonIndex?'active':''}">${l.name}</button>`).join('')}</div><div id="game-wrap"></div>${field('rhythm-note','Transfer zu Lösel: Wo würdest du in „intro zwei.“ Gewicht und Pausen setzen?','Begründe zwei Entscheidungen am Sinn. Ein Zeilenbruch ist nicht automatisch eine Pause; freie Verse brauchen kein regelmässiges Versmass.')}${complete()}`;}
function workshop(){return head('Nicht nur lesen.<br><em>Etwas sagen.</em>','Eine Werkstatt mit Verfahren, die du bei Lösel untersuchen kannst. Du arbeitest mit Alltagsbildern, direkter Anrede und Wendungen – und entwickelst daraus deine eigene Stimme.')+`${state.notes['inspiration-impuls']?`<article class="card inspiration-picked"><p class="eyebrow">DEINE SCHREIBIDEE</p><p>${esc(state.notes['inspiration-impuls'])}</p><a href="#inspiration">Weitere Inspiration auswählen</a></article>`:'<p><a href="#inspiration">Gedichte, Filme und Poetologie als Inspiration entdecken</a></p>'}<div class="tabs" role="group" aria-label="Werkstattbereiche"><button data-work="impuls" class="active">Wortfunken</button><button data-work="baukasten">D-Gram-Regel-Editor</button><button data-work="analyse">Textlupe</button><button data-work="buehne">Deine Bühne</button></div><section id="work-area"></section>${complete()}`;}
function nav(){const n=state.done.length;$('#nav').innerHTML=sections.map((s,i)=>`<a href="#${s[0]}" class="${route===s[0]?'active':''}" ${route===s[0]?'aria-current="step"':''}><span class="num">${String(i+1).padStart(2,'0')}</span>${s[1]}${state.done.includes(s[0])?'<span class="done">✓</span>':''}</a>`).join('')+`<a href="#inspiration" class="${route==='inspiration'?'active':''}" ${route==='inspiration'?'aria-current="page"':''}><span class="num">✦</span>Inspiration</a>`;$('#progress-label').textContent=`${n} von 5 Stationen entdeckt`;$('#progress-bar').style.width=n*20+'%';}
function render(){game=null;route=location.hash.slice(1);if(route!=='inspiration'&&!sections.some(s=>s[0]===route))route='ankommen';$('#main').innerHTML=({ankommen:landing,lesen:reading,hoeren:hearing,rhythmus:rhythm,werkstatt:workshop,inspiration:inspiration}[route])();nav();if(route==='rhythmus')startGame();if(route==='werkstatt'){work(pendingWork||'impuls');pendingWork=null;}if(route==='inspiration')bindInspiration();bindReelGallery();bindSave();if($('#complete'))$('#complete').onclick=()=>{if(!state.done.includes(route))state.done.push(route);save();nav();$('#complete').textContent='Erledigt ✓';toast('Gespeichert.');};$('#journal-export')?.addEventListener('click',exportJournal);$('#landing-teacher')?.addEventListener('click',()=>$('#help').click());$('#reading-hint')?.addEventListener('click',()=>modal('<h2>Eine mögliche Lesart</h2><p>Das Alltagswort „tesa“ trifft auf etwas kaum Festzuhaltendes: Tränen. Das kann provisorisches Reparieren, Schutz oder mühsames Zusammenhalten nahelegen. Die Zeilen erscheinen als Verpackung des Gefühls. Das Bild bleibt ambivalent: Schreiben kann etwas halten, ohne die Verletzung verschwinden zu lassen.</p><p>Begründe deine Lesart am Wortlaut. „Heilen“ eröffnet einen Prozess; „noch“ hält seine Unabgeschlossenheit offen. Auch andere begründete Deutungen sind möglich.</p>'));document.querySelectorAll('[data-annotation]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-annotation]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#annotation-feedback').textContent={heilen:'„heilen“: ein Prozess statt eines fertigen Zustands. Welche Wirkung hat das zeitliche „noch“?',tesa:'Alltagsgegenstand + Gefühl: eine ungewohnte Verbindung. Kann Klebeband Tränen halten? Gerade der Widerspruch lässt das Bild arbeiten.',zeilen:'Der Text spricht über sein eigenes Medium: Schreiben wird als Verpacken vorgestellt. Was bewahrt, was verdeckt eine Verpackung?'}[b.dataset.annotation];});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lessonIndex=+b.dataset.lesson;render();});document.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>work(b.dataset.work));}
function bindSave(){document.querySelectorAll('[data-save]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.save]=el.value;save();}));}
function modal(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal();}
$('.dialog-close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('close',()=>$('#resource-player-area')?.replaceChildren());$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close();});
function startGame(){game={prefix:'',boundary:false,errors:0,times:[],started:0,ended:false};paused=false;const l=lessons[lessonIndex];$('#game-wrap').innerHTML=`<div class="game"><div class="game-stats"><span>${l.name} · selbst bestimmtes Tempo</span><span id="game-stat">Bereit</span></div><p class="small" style="margin-top:18px">${l.note}</p><div class="syllables" id="syllables"></div><div class="keys"><button data-hit="0" aria-label="Unbetont">∪<small>unbetont · F</small></button><button data-hit="1" aria-label="Betont">–<small>betont · J</small></button><button data-hit="b" aria-label="Zäsur oder Enjambement">| /<small>Grenze · Leertaste</small></button></div><div class="feedback" id="game-feedback" role="status">Lies die Zeile laut. Beginne, wenn du bereit bist.</div><div class="mode-options"><label><input type="checkbox" id="soft" ${soft?'checked':''}> Verzeihend</label><label><input type="checkbox" id="invert" ${invert?'checked':''}> F/J tauschen</label><button id="pause">Pause · P</button><button id="restart">Neu beginnen</button></div><p class="small" style="margin-top:15px">Fehler: im verzeihenden Modus dieselbe Silbe, sonst den ganzen Vers wiederholen. Kein Zeitlimit, kein Punktabzug. Silbenmarkierungen erscheinen nach jedem Schritt.</p></div>`;drawGame();document.querySelectorAll('[data-hit]').forEach(b=>b.onclick=()=>hit(b.dataset.hit));$('#soft').onchange=e=>soft=e.target.checked;$('#invert').onchange=e=>invert=e.target.checked;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'Fortsetzen · P':'Pause · P';$('#game-stat').textContent=paused?'Pausiert':'Bereit zum Weiterlesen';};$('#restart').onclick=startGame;}
function drawGame(){const l=lessons[lessonIndex];$('#syllables').innerHTML=l.syllables.map((s,i)=>`<span class="syllable ${i<game.prefix.length?'correct':i===game.prefix.length?'current':''}">${esc(s)}<span class="scan">${i<game.prefix.length?(game.prefix[i]==='1'?'–':'∪'):''}</span>${l.boundary===i+1?`<small style="font:13px system-ui">${game.boundary?'✓':'◇'}</small>`:''}</span>`).join('');}
function tone(freq=180){if(!ctx||ctx.state!=='running')return;const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.025,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.15);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.16);}
function hit(value){if(!game||paused||game.ended)return;const l=lessons[lessonIndex],feedback=$('#game-feedback');if(value==='b'){if(game.prefix.length===l.boundary&&!game.boundary){game.boundary=true;feedback.textContent=`${l.boundaryType} markiert. Lies weiter.`;drawGame();}else feedback.textContent='An dieser Stelle ist keine zusätzliche Grenze vorgesehen.';return;}
 if(l.boundary===game.prefix.length&&!game.boundary){feedback.textContent=`Markiere zuerst das ${l.boundaryType==='Zäsur'?'Innehalten':'Weiterlaufen über die Versgrenze'} mit der Grenztaste.`;return;}
 const next=game.prefix+value;if(!validPatterns(l,next).length){game.errors++;feedback.textContent=soft?'Versuche diese Silbe noch einmal. Sprich das Wort im Zusammenhang.':'Noch einmal vom Versanfang. Lies die Zeile vor dem Tippen.';if(!soft){game.prefix='';game.boundary=false;game.times=[];game.started=0;}drawGame();return;}
 const now=performance.now();if(!game.started)game.started=now;else game.times.push(now-game.last);game.last=now;game.prefix=next;tone(value==='1'?230:145);drawGame();feedback.textContent='Lies weiter – dein Lesen gibt den Takt vor.';
 if(game.prefix.length===l.syllables.length){game.ended=true;const seconds=(now-game.started)/1000,rate=seconds>0?Math.round((l.syllables.length-1)/seconds*60):0;let timing='';if(l.quiet&&game.times.length>1){const avg=game.times.reduce((a,b)=>a+b,0)/game.times.length;const cv=Math.sqrt(game.times.reduce((a,b)=>a+(b-avg)**2,0)/game.times.length)/avg;timing=` Gleichmass deiner Tastenabstände: ${cv<.25?'ruhig und gleichmässig':'noch wechselnd'}. Das ist eine Rückmeldung zum Tippen, keine Bewertung deines Vortrags.`;}feedback.textContent=l.explain+timing;$('#game-stat').textContent=`Erkundet ✓ · ${game.errors} Versuche korrigiert${l.quiet?'':` · ${rate} Silben/Min.`}`;state.notes['labor-'+lessonIndex]=`${l.name}: ${game.prefix}; ${game.errors} Korrekturen.`;save();}}
document.addEventListener('keydown',e=>{if(route!=='rhythmus'||$('#dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable)return;let k=e.key.toLowerCase(),v=null;if(k==='f'||k==='arrowleft')v=invert?'1':'0';if(k==='j'||k==='arrowright')v=invert?'0':'1';if(k===' '||k==='arrowdown')v='b';if(v!==null){e.preventDefault();if(!e.repeat)hit(v);}if(k==='p'&&!e.repeat){e.preventDefault();$('#pause').click();}});
const dilaits='https://patrickfischerksa.github.io/dilaits_Bubenhofer_Peric_angepasst_FiP/';
function work(name){document.querySelectorAll('[data-work]').forEach(b=>b.classList.toggle('active',b.dataset.work===name));const a=$('#work-area');if(name==='impuls'){a.innerHTML=`<div class="two-col"><div>${state.notes['inspiration-impuls']?'<h2>Beginne mit deiner Schreibidee.</h2><p class="intro">Der gewählte Vorschlag steht oben. Sammle zunächst Wörter und Bilder, die dazu passen. Schreibe dann einige Verse, ohne sie gleich zu beurteilen.</p>':'<h2>Ein Alltagsding. Ein Gefühl.</h2><p class="intro">Bei „intro zwei.“ verbinden sich Klebeband und Tränen. Suche selbst eine unerwartete Verbindung und entwickle ein anderes Bild.</p><div class="card"><p class="eyebrow">DEIN SCHREIBIMPULS</p><div id="prompt" class="verse-display">Ein Schlüsselbund.<br>Eine unausgesprochene Entschuldigung.</div><button id="new-prompt">Anderen Impuls ziehen</button></div>'}<h3 style="margin-top:23px">Vier Schritte zum Rohtext</h3><ol class="small"><li>Beschreibe einen konkreten Moment, ohne ihn gleich zu erklären.</li><li>Sprich ein „du“ an oder lass ein „ich“ sprechen.</li><li>Wiederhole einen Satzanfang und verändere, was folgt.</li><li>Lass die letzte Zeile die vorherigen neu beleuchten.</li></ol><p class="small">Dein Text muss weder reimen noch autobiografisch sein. Die Wirkung ist wichtiger als das Abarbeiten aller vier Schritte.</p></div><div>${field('draft','Dein Rohtext','Welche Dinge tragen ein Gefühl? Beginne mit einer Beobachtung …')}<button id="take-draft">Als Arbeitsfassung übernehmen</button>${field('intention','Was soll dein Text bei den Lesenden auslösen?','Beschreibe eine Absicht. Du kannst sie später ändern.')}</div></div>`;if($('#new-prompt'))$('#new-prompt').onclick=()=>{const objects=['Eine leere Brotdose.','Ein Ladekabel.','Ein beschlagener Spiegel.','Ein Bus, der zu früh kommt.','Ein ungeöffneter Brief.'];const feelings=['Der Wunsch, dazuzugehören.','Eine Freundschaft, die leiser wird.','Mut vor dem ersten Schritt.','Das Gefühl, zu spät zu sein.','Ein unerwarteter Neuanfang.'];$('#prompt').textContent=objects[Math.floor(Math.random()*objects.length)]+'\n'+feelings[Math.floor(Math.random()*feelings.length)];};$('#take-draft').onclick=()=>{if(!(state.notes.draft||'').trim())return toast('Schreibe zuerst einen Rohtext.');state.notes.poem=state.notes.draft;save();work('buehne');};}
if(name==='baukasten'){renderGrammarEditor(a);}
if(name==='analyse'){a.innerHTML=`<p class="intro">Eine Textlupe nach Anna-Lizas Prinzipien: Häufigkeiten, wiederholte Wortfolgen und Kontextfenster machen Muster sichtbar. Du deutest ihre Wirkung.</p><div class="two-col"><div>${field('corpus','Untersuchungstext A','Füge deinen Entwurf oder eine rechtmässig verfügbare Textstelle ein.')}<div class="actions"><button id="load-poem">Arbeitsfassung einsetzen</button><button class="primary" id="analyze">Text untersuchen</button></div><label class="field" for="term">Suchwort für Kontextfenster (genaue Wortform)</label><input type="text" id="term" placeholder="z. B. ich">${field('corpus-b','Optional: Vergleichstext B','Füge eine frühere Fassung oder einen anderen Text ein.')}<p class="small">Die lokale Lupe zählt Wortformen, keine Lemmata. Grossschreibung wird ignoriert; Funktionswörter bleiben sichtbar. Kurze Texte und Wortzahlen sind keine Stilbeweise.</p><a href="${dilaits}" target="_blank" rel="noopener noreferrer">Im Original: Anna-Liza öffnen</a></div><div><h2>Was dein Text oft sagt.</h2><div id="analysis-result" aria-live="polite" class="card">Füge einen Text ein und untersuche ihn.</div></div></div>${field('analysis-note','Vom Zählen zum Verstehen: Welche Wiederholung trägst du bewusst weiter?','Nenne das Muster, seine Stelle und seine Wirkung. Was änderst du nach dem Vergleich?')}`;$('#load-poem').onclick=()=>{$('#corpus').value=state.notes.poem||state.notes.draft||'';state.notes.corpus=$('#corpus').value;save();};$('#analyze').onclick=()=>{const text=$('#corpus').value;if(!text.trim())return toast('Füge zuerst einen Text ein.');const result=analyze(text,$('#term').value),b=$('#corpus-b').value;$('#analysis-result').innerHTML=`<h3>${result.words} Wörter · ${result.types} Wortformen · ${result.lines} Zeilen</h3><p class="small">Häufige Wortformen</p><div class="choice">${result.freq.map(([w,c])=>`<span class="pill">${esc(w)} · ${c}</span>`).join('')}</div><h3 style="margin-top:24px">Wiederholte Folgen (3–6 Wörter)</h3>${result.ngrams.length?result.ngrams.map(([w,c])=>`<p class="small">„${esc(w)}“ · ${c}×</p>`).join(''):'<p class="small">Keine wiederholten Wortfolgen dieser Länge.</p>'}<h3>Suchwort im Kontext</h3>${result.kwic.length?result.kwic.slice(0,30).map(k=>`<p class="small">${esc(k.left)} <strong style="color:var(--coral)">${esc(k.word)}</strong> ${esc(k.right)}</p>`).join(''):'<p class="small">Kein Suchwort oder keine genaue Übereinstimmung.</p>'}${b.trim()?`<h3>Vergleich mit Text B</h3><p class="small">B: ${analyze(b).words} Wörter · ${analyze(b).types} Wortformen · ${analyze(b).lines} Zeilen. Prüfe, ob Unterschiede an Länge, Thema oder Überarbeitung liegen.</p>`:''}`;};}
if(name==='buehne'){a.innerHTML=`<div class="two-col"><div>${field('poem','Deine Arbeitsfassung','Hier entsteht dein eigener Text …')}<p class="small" id="poem-count"></p>${field('revision','Überarbeitung: vorher → nachher → beabsichtigte Wirkung','Ersetze eine abstrakte Aussage durch ein konkretes Bild. Begründe einen Zeilenbruch. Prüfe die letzte Zeile.')}${state.notes.previous?`<details><summary>Vorige Arbeitsfassung</summary><pre style="white-space:pre-wrap">${esc(state.notes.previous)}</pre></details>`:''}<div class="actions"><button class="primary" id="export-poem">Gedicht als Text sichern</button><button id="print-poem">Druckansicht</button></div></div><div class="card writing-preview"><p class="eyebrow">DEINE WORTE, DEINE STIMME</p><div class="verse-display" id="poem-preview"></div><div class="divider"></div><h3>Vor dem Vortragen</h3><ul class="checklist">${[['image','Ein Bild ist konkret und überraschend.'],['break','Ein Zeilenbruch verändert hörbar die Wirkung.'],['turn','Mein Schluss öffnet oder verschiebt den Gedanken.'],['voice','Ich habe den Text laut gelesen und Pausen erprobt.']].map(([id,t])=>`<li><label><input type="checkbox" data-check="${id}" ${state.notes['check-'+id]==='ja'?'checked':''}>${t}</label></li>`).join('')}</ul><p class="small">Die Checkliste hilft beim Überarbeiten. Sie vergibt keine Note und erklärt keinen Text automatisch für gelungen.</p></div></div>${field('exit','Zum Schluss: Was kann dein Gedicht jetzt, was dein erster Entwurf noch nicht konnte?','Belege deine Antwort an einer konkreten Änderung. Was möchtest du weiter ausprobieren?')}`;const update=()=>{$('#poem-preview').textContent=$('#poem').value||'Hier bekommen deine Worte Raum.';const x=analyze($('#poem').value);$('#poem-count').textContent=`${x.words} Wörter · ${x.lines} Zeilen`;};update();$('#poem').addEventListener('input',update);document.querySelectorAll('[data-check]').forEach(c=>c.onchange=()=>{state.notes['check-'+c.dataset.check]=c.checked?'ja':'nein';save();});$('#export-poem').onclick=()=>download('mein-gedicht.txt',$('#poem').value);$('#print-poem').onclick=()=>{modal(`<h2>Mein Gedicht</h2><div class="verse-display">${esc($('#poem').value)}</div><div class="actions"><button id="print-now">Jetzt drucken</button></div>`);$('#print-now').onclick=()=>window.print();};}bindSave();}
function exportJournal(){const labels={start:'Mein Wort zum Einstieg',deutung:'Textdeutung',bruch:'Zeilenbruch',vergleich:'Textvergleich',quelle:'Hörquelle',hoeren:'Hörbeobachtung',wirkung:'Wirkung',medium:'Plattform',draft:'Rohtext',poem:'Eigenes Gedicht',revision:'Überarbeitung',exit:'Rückblick'};download('mein-lyrikjournal.txt',`ZWISCHEN DEN ZEILEN · LERNJOURNAL\n${new Date().toLocaleDateString('de-CH')}\n\n`+Object.entries(state.notes).map(([k,v])=>`${labels[k]||k}\n${v}\n`).join('\n'));}
$('#backup').onclick=()=>download('lyriklabor-sicherung.json',JSON.stringify(state,null,2),'application/json');$('#restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3000000)throw Error('Datei zu gross.');const next=JSON.parse(await file.text());if(!validateSave(next))throw Error('Keine gültige Lyriklabor-Sicherung.');modal('<h2>Sicherung laden?</h2><p>Die Einträge in diesem Browser werden durch die gewählte Sicherung ersetzt. Sichere vorher bei Bedarf dein aktuelles Journal.</p><button id="confirm-restore" class="primary">Sicherung übernehmen</button>');$('#confirm-restore').onclick=()=>{state={version:1,done:[...new Set(next.done)],notes:Object.fromEntries(Object.entries(next.notes))};save();$('#dialog').close();render();toast('Sicherung geladen.');};}catch(e){toast(e.message);}e.target.value='';};
$('#reset').onclick=()=>{modal('<h2>Neu anfangen?</h2><p>Damit löschst du die Texte und den Fortschritt dieses Lyriklabors in diesem Browser. Lade zuerst eine Sicherung herunter, wenn du sie behalten möchtest.</p><div class="actions"><button id="reset-backup">Vorher Sicherung herunterladen</button><button id="confirm-reset">Einträge jetzt löschen</button></div>');$('#reset-backup').onclick=$('#backup').onclick;$('#confirm-reset').onclick=()=>{state={version:1,done:[],notes:{}};save();$('#dialog').close();render();toast('Lokaler Lernstand gelöscht.');};};
$('#help').onclick=()=>modal(`<h2>Eine Doppelstunde mit Spielraum.</h2><p>Für Sekundarstufe II / ab 16 Jahren, etwa 90–105 Minuten. Lernende analysieren sprachliche Verfahren, begründen Vortragsentscheidungen und überarbeiten einen eigenen lyrischen Text.</p><h3>Ablauf</h3><ol><li>Ankommen (5 Min.): Wortimpuls, freiwilliger Austausch.</li><li>Lesen (20 Min.): Einzeldeutung, danach Vergleich mit „lange version.“.</li><li>Hören (15 Min.): Plattformbeobachtung oder zwei eigene Lesarten.</li><li>Rhythmus (20 Min.): ausgewählte Werkstätten; Transfer zu freien Versen.</li><li>Schreiben (30–45 Min.): Rohtext, Regelvariation, Textlupe, Überarbeitung und freiwilliger Vortrag.</li></ol><h3>Differenzierung und Rückmeldung</h3><p>Basis: Jambus und Trochäus, ein Bild und ein begründeter Zeilenbruch. Erweiterung: Zäsur, Enjambement, mehrere Lesarten, eigener D-Gram-Regelsatz und Vergleich zweier Fassungen. Rückmeldung zu Textbelegen, begründeter Wirkung und sichtbarer Überarbeitung. Persönliche Offenheit wird nicht bewertet.</p><h3>Material und Datenschutz</h3><p>Für die zweite Lektüre wird das rechtmässig verfügbare Buch/PDF benötigt. Es wird hier nicht verbreitet. Externe Hörquellen sind optional. Lernjournal und Textlupe laufen lokal; ein geteiltes Gerät kann Einträge sichtbar machen. Einträge können exportiert und gelöscht werden. Der Fortschrittsknopf dokumentiert Selbsteinschätzung, keine Leistungsprüfung.</p><p>Die ausführliche Planung und Quellen stehen im GitHub-Paket unter docs/.</p>`);
$('#sources').onclick=()=>modal(`<h2>Woher die Worte kommen.</h2><ul class="source-list"><li>Clara Lösel: <cite>Wehe du gibst auf. 101 x Clartext, der dein Denken verändert</cite>. NOW, 2025. ISBN 9783689690229. „intro zwei.“ wird als kurzer Gegenstand der Textanalyse wiedergegeben. Bezug: bereitgestellte PDF, PDF-Seite 15. „lange version.“: PDF-Seite 17. Keine Weitergabe des vollständigen PDFs.</li><li><a href="https://claraloesel.de/" target="_blank" rel="noopener noreferrer">Offizielle Website</a> · <a href="https://www.instagram.com/claraloesel/" target="_blank" rel="noopener noreferrer">Instagram @claraloesel</a> · <a href="https://open.spotify.com/search/clara%20l%C3%B6sel" target="_blank" rel="noopener noreferrer">Spotify-Suche</a>. Originalmedien werden über ihre Anbieter eingebettet. Das Porträtmotiv stammt von der offiziellen Website und ist dort nachgewiesen.</li><li><a href="https://duxludens.itch.io/metrum" target="_blank" rel="noopener noreferrer">metrum ludens · duxludens</a>: Anregung für selbst bestimmtes Silbentippen, zwei Betonungstasten, Grenzmarkierungen, mehrere Lesarten, verzeihenden Modus und Stille. Eigenständige Implementierung mit eigenen Übungsversen; kein übernommener Spielcode.</li><li><a href="${dilaits}" target="_blank" rel="noopener noreferrer">DILAITS · Bubenhofer / Perić, angepasste Fassung FiP</a>: Anna-Liza (Frequenzen, N-Gramme, KWIC, Korpusvergleich) und D-Gram (Regeln, Wortschatz, Digital Poet) als didaktische Anregung. Lokale vereinfachte Umsetzung mit Regel-Editor, Ableitungsansicht und Export für die Originalwerkzeuge. Kein übernommener Quellcode.</li></ul><p>Quellen geprüft am 27.11.2026. Unabhängiges Bildungsprojekt, keine offizielle Seite der Autorin. Alle nicht anders bezeichneten Übungsverse sind für diese Einheit verfasst. Porträtmotiv: claraloesel.de, keyvisual-claral-loesel-2.jpg. Klang: lokal synthetisiert. Die Website selbst setzt keine Analyse- oder Trackingdienste ein; Instagram-Einbettungen stellen eine Verbindung zu Instagram her.</p>`);
$('#sound').onclick=async()=>{try{if(!ctx)ctx=new AudioContext();if(ambient){ambient.stop();ambient=null;$('#sound').textContent='◌ Klang aus';$('#sound').setAttribute('aria-pressed','false');return;}await ctx.resume();const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=110;g.gain.value=.014;o.connect(g).connect(ctx.destination);o.start();ambient=o;$('#sound').textContent='◉ Klang an';$('#sound').setAttribute('aria-pressed','true');}catch{toast('Klang wird in diesem Browser nicht unterstützt.');}};
window.addEventListener('hashchange',()=>{render();$('#main').focus();window.scrollTo(0,0);});render();if(!storage)toast('Bitte sichere dein Journal als Datei; Browserspeicher ist nicht verfügbar.');
function renderGrammarEditor(area){
 const rules=state.notes['grammar-rules']??DEFAULT_RULES;
 let words=state.notes['grammar-words'];
 if(words===undefined){const keys=['objects','feelings','actions'];words=keys.some(k=>state.notes[k])?keys.map((k,i)=>`${['Ding','Bild','Tun'][i]} -> ${(state.notes[k]||['einen Schlüssel, ein Fenster','einen Anfang, ein leises Nein','bleiben, zuhören'][i]).split(',').map(t=>JSON.stringify(t.trim())).join(' | ')}`).join('\n'):DEFAULT_WORDS;}
 area.innerHTML=`<p class="intro">Dein D-Gram-Regel-Editor: Gib Sprache einen Bauplan, verändere die Wortfelder und erzeuge Verse direkt hier. Jede Kombination ist Material für deine eigene Überarbeitung.</p>
 <section class="grammar-library" aria-labelledby="library-heading"><h2 id="library-heading">Meine Grammatikbibliothek</h2><p class="small">Speichere Regeln, Wortfelder, Startsymbol und Versanzahl unter einem eigenen Namen. Deine Sammlung bleibt in diesem Browser und ist Teil der Lernjournal-Sicherung.</p><label class="field" for="grammar-name">Name für den aktuellen Bauplan</label><input type="text" id="grammar-name" maxlength="80" data-save="grammar-name" value="${esc(state.notes['grammar-name']||'')}" placeholder="z. B. Fensterbilder – erste Fassung"><div class="actions"><button class="primary" id="grammar-save-named">Unter diesem Namen speichern</button></div><label class="field" for="grammar-saved-select">Gespeicherte Grammatik auswählen</label><select id="grammar-saved-select"></select><div class="actions"><button id="grammar-load-saved">Gespeicherte Grammatik laden</button><button id="grammar-export-saved">Auswahl als Grammatikdatei exportieren</button></div><label class="field" for="grammar-import">Grammatikdatei importieren (.json)</label><input type="file" id="grammar-import" accept="application/json,.json" aria-describedby="grammar-import-hint"><p class="small" id="grammar-import-hint">Importierte Dateien werden als neuer Eintrag ergänzt. Bei gleichem Namen erhalten sie einen Zusatz; vorhandene Grammatiken bleiben erhalten. Zum Bearbeiten anschliessend laden.</p><div id="grammar-library-status" class="feedback" role="status" aria-live="polite">Auch unfertige Entwürfe können gespeichert werden. Exportiere wichtige Baupläne als Datei, bevor du Browserdaten löschst.</div></section><section class="grammar-examples" aria-labelledby="examples-heading"><h2 id="examples-heading">Mit einem Beispiel anfangen</h2><p class="small">Wähle ein sprachliches Verfahren. Lies den Auftrag und lade den Bauplan, wenn du damit arbeiten möchtest.</p><label class="field" for="grammar-example-select">Beispielgrammatik auswählen</label><select id="grammar-example-select">${['Anaphern','Metaphern','Überraschende Wendungen'].map(category=>`<optgroup label="${category}">${GRAMMAR_EXAMPLES.filter(example=>example.category===category).map(example=>`<option value="${example.id}" ${example.id===state.notes['grammar-example-selected']?'selected':''}>${esc(example.title)}</option>`).join('')}</optgroup>`).join('')}</select><div id="grammar-example-info" aria-live="polite"></div><div class="actions"><button class="primary" id="grammar-load-example">Beispiel in den Editor laden</button><button id="grammar-undo-example" ${state.notes['grammar-previous-rules']===undefined?'disabled':''}>Vorherigen Bauplan wiederherstellen</button></div><p class="small">Beim Laden wird dein bisheriger Bauplan zwischengespeichert. Dein Gedicht und die letzte Versausgabe bleiben erhalten. Alle Beispiele sind eigens geschriebenes Übungsmaterial.</p></section><div class="grammar-layout"><div><h2>Dein Bauplan für Sprache</h2><label class="field" for="grammar-rules">Regeln</label><textarea class="code-editor" id="grammar-rules" data-save="grammar-rules" spellcheck="false" aria-describedby="grammar-hint">${esc(rules)}</textarea>
 <section class="wordfield-editor" aria-labelledby="wordfield-heading"><h2 id="wordfield-heading">Deine Wörter und Bilder</h2><p class="small">Ändere Wörter oder ganze Wendungen direkt in den Feldern. Mit „Eintrag hinzufügen“ sammelst du weitere Möglichkeiten. Anführungszeichen und andere Satzzeichen kannst du ganz normal schreiben.</p><form id="wordfield-create" class="wordfield-create"><h3>Ein eigenes Wortfeld anlegen</h3><label class="field" for="wordfield-name">Name des Wortfelds</label><input id="wordfield-name" type="text" maxlength="60" placeholder="z. B. Erinnerungen oder Meine Farben" aria-describedby="wordfield-name-hint"><p class="small" id="wordfield-name-hint">Leerzeichen im Namen werden zu Unterstrichen, damit du das Feld auch in Regeln verwenden kannst.</p><label class="field" for="wordfield-first-entries">Erste Wörter oder Wendungen · ein Eintrag pro Zeile</label><textarea id="wordfield-first-entries" rows="3" placeholder="Licht im Treppenhaus&#10;ein vertrauter Geruch&#10;die letzte Seite im Heft"></textarea><label class="wordfield-try"><input type="checkbox" id="wordfield-use-new"> Das neue Wortfeld direkt zum Erzeugen verwenden</label><p class="small">Mit dieser Option wird das neue Feld zum Startsymbol: Die nächste Ausgabe kombiniert zunächst nur seine Einträge. Deine bisherigen Regeln bleiben erhalten.</p><button type="submit" class="primary">Wortfeld anlegen</button><p id="wordfield-status" class="small" role="status" aria-live="polite"></p></form><div id="wordfield-forms"></div></section>
 <details class="wordfield-source"><summary>Wortfelder als Text bearbeiten</summary><label class="field" for="grammar-words">Wortfelder</label><textarea class="code-editor" id="grammar-words" data-save="grammar-words" spellcheck="false" aria-describedby="grammar-hint">${esc(words)}</textarea><p class="small">Textansicht und Eingabefelder zeigen dieselben Wortfelder. Änderungen werden in beide Richtungen übernommen. Regeln mit Verweisen auf andere Bausteine bearbeitest du hier.</p></details>
 <div class="grammar-controls"><div><label class="field" for="grammar-start">Startsymbol</label><input type="text" id="grammar-start" data-save="grammar-start" value="${esc(state.notes['grammar-start']??'S')}" spellcheck="false"></div><div><label class="field" for="grammar-count">Anzahl Verse (1–24)</label><input type="number" id="grammar-count" min="1" max="24" step="1" value="${esc(state.notes['grammar-count']??'4')}" data-save="grammar-count"></div></div>
 <div class="actions"><button id="grammar-check">Regeln prüfen</button><button class="primary" id="grammar-generate">Verse erzeugen</button></div><div id="grammar-status" class="feedback" role="status" aria-live="polite">Ändere einen Bauplan oder ein Wortfeld und prüfe deine Regeln.</div>
 <details><summary>Syntax und Ideen zum Experimentieren</summary><div id="grammar-hint"><p><code>S -&gt; Anrede Ding "."</code> setzt eine Zeile aus Bausteinen zusammen. <code>Ding -&gt; "einen Schlüssel" | "ein Fenster"</code> stellt Alternativen bereit. Bausteinnamen beachten Gross- und Kleinschreibung.</p><ul class="small"><li>Eigene Namen wie <code>Zeile</code>, <code>Bild</code> oder <code>Wendung</code> verwenden und überall gleich schreiben.</li><li>Wörter und Satzzeichen in einfache oder doppelte Anführungszeichen setzen. Mehrere Wörter dürfen zusammen darin stehen.</li><li><code>|</code> trennt Alternativen; <code>#</code> beginnt einen Kommentar ausserhalb von Anführungszeichen.</li><li>Für einen Zeilenbruch <code>"\\n"</code> einsetzen. Regeln können andere Regeln enthalten.</li><li>Regeln und Wortfelder werden gemeinsam ausgewertet. Das Startsymbol bestimmt, womit jede Erzeugung beginnt.</li></ul><p class="small">Eigenständige, vereinfachte Umsetzung nach D-Gram: kontextfreie Regeln, keine Merkmale wie <code>[NUM=sg]</code>, keine automatische Kongruenz und keine vollständige D-Gram-Engine. Wähle passende Wortformen selbst. Satzzeichen . , ! ? ; : schliessen ohne zusätzliches Leerzeichen an. Zufall prüft weder Sinn noch Qualität.</p></div></details>
 <div class="actions"><button id="grammar-download">Regeln als Text herunterladen</button></div><p class="small">Deine Regeln und Wortfelder werden mit dem Lernjournal lokal gespeichert.</p><a href="${dilaits}" target="_blank" rel="noopener noreferrer">DILAITS als ergänzende Originalressource</a></div>
 <div><article class="card grammar-output"><p class="eyebrow">DEINE REGELN WERDEN ZU WORTEN</p><div id="generated" class="verse-display">${esc(state.notes.generated||'Hier erscheinen deine Verse.')}</div><div class="actions"><button id="take-generated">In die Arbeitsfassung übernehmen</button></div><p class="small">Welche Kombination überrascht? Welche bleibt beliebig? Ändere ein Wortfeld, vergleiche zwei Fassungen und schreibe den Schluss selbst weiter.</p></article><details class="grammar-trace"><summary>Ableitung der letzten Erzeugung</summary><pre id="grammar-trace">${esc(state.notes['grammar-trace']||'Nach dem Erzeugen siehst du hier, welche Regeln gewählt wurden.')}</pre><p class="small">Eine Änderung im Editor verändert die letzte Ausgabe erst beim erneuten Erzeugen.</p></details></div></div>
 ${field('generation-reflection','Was bewirken deine Regeln – und was entscheidest du beim Überarbeiten selbst?','Vergleiche zwei Regelvarianten. Nenne eine bewusste Änderung und ihre Wirkung.')}`;
 const persistEditor=()=>{for(const id of ['grammar-rules','grammar-words','grammar-start','grammar-count'])state.notes[id]=$('#'+id).value;save();};
 const status=(text,error=false)=>{const el=$('#grammar-status');el.textContent=text;el.classList.toggle('error',error);};
 bindWordFieldEditor(persistEditor,status);
 const compile=()=>{persistEditor();return compileGrammar($('#grammar-rules').value,$('#grammar-words').value,$('#grammar-start').value.trim());};
 const libraryStatus=(message,error=false)=>{const el=$('#grammar-library-status');el.textContent=message;el.classList.toggle('error',error);};
 const library=()=>decodeLibrary(state.notes['grammar-library']||'');
 const refreshLibrary=()=>{try{const entries=library();const chosen=state.notes['grammar-library-selected']||'';$('#grammar-saved-select').innerHTML='<option value="">Gespeicherten Bauplan wählen …</option>'+entries.map(item=>`<option value="${esc(item.name)}" ${item.name===chosen?'selected':''}>${esc(item.name)}</option>`).join('');const enabled=entries.some(item=>item.name===chosen);$('#grammar-load-saved').disabled=!enabled;$('#grammar-export-saved').disabled=!enabled;}catch(e){libraryStatus('Die Bibliothek konnte nicht gelesen werden: '+e.message,true);}};
 const writeLibrary=(next,selected)=>{state.notes['grammar-library']=JSON.stringify(next);state.notes['grammar-library-selected']=selected;save();refreshLibrary();};
 const selectedGrammar=()=>{const entry=library().find(item=>item.name===$('#grammar-saved-select').value);if(!entry)throw Error('Wähle zuerst eine gespeicherte Grammatik.');return entry;};
 const snapshot=()=>{persistEditor();for(const key of ['rules','words','start','count'])state.notes['grammar-previous-'+key]=state.notes['grammar-'+key];};
 refreshLibrary();
 $('#grammar-saved-select').onchange=()=>{state.notes['grammar-library-selected']=$('#grammar-saved-select').value;save();refreshLibrary();};
 $('#grammar-save-named').onclick=()=>{try{persistEditor();const entry=namedGrammar({name:$('#grammar-name').value,rules:$('#grammar-rules').value,words:$('#grammar-words').value,start:$('#grammar-start').value,count:Number($('#grammar-count').value)}),entries=library();const storeEntry=replace=>{writeLibrary(putGrammar(entries,entry,replace),entry.name);state.notes['grammar-name']=entry.name;$('#grammar-name').value=entry.name;save();libraryStatus(`„${entry.name}“ in deiner Bibliothek gespeichert. Änderungen im Editor werden erst durch erneutes Speichern in diesen Eintrag übernommen.`);};if(entries.some(item=>item.name.normalize('NFC').toLocaleLowerCase('de')===entry.name.toLocaleLowerCase('de'))){modal(`<h2>Gespeicherte Grammatik ersetzen?</h2><p>Unter „${esc(entry.name)}“ gibt es bereits einen Bauplan. Du kannst ihn durch den aktuellen Editorinhalt ersetzen oder den Dialog schliessen und einen anderen Namen vergeben.</p><button class="primary" id="grammar-confirm-replace">Gespeicherten Bauplan ersetzen</button>`);$('#grammar-confirm-replace').onclick=()=>{try{storeEntry(true);$('#dialog').close();}catch(e){toast(e.message);}};}else storeEntry(false);}catch(e){libraryStatus(e.message,true);}};
 $('#grammar-load-saved').onclick=()=>{try{const entry=selectedGrammar();snapshot();for(const key of ['rules','words','start','count'])state.notes['grammar-'+key]=String(entry[key]);state.notes['grammar-name']=entry.name;delete state.notes['grammar-example-loaded'];save();work('baukasten');$('#grammar-library-status').textContent=`„${entry.name}“ geladen. Der vorherige Editorinhalt kann über „Vorherigen Bauplan wiederherstellen“ zurückgeholt werden.`;}catch(e){libraryStatus(e.message,true);}};
 $('#grammar-export-saved').onclick=()=>{try{const entry=selectedGrammar();download(entry.name.replace(/[^\p{L}\p{N}_-]+/gu,'-')+'.grammatik.json',exportGrammar(entry),'application/json');libraryStatus(`„${entry.name}“ als Grammatikdatei exportiert. Exportiert wurde der gespeicherte Stand; speichere Editoränderungen vorher unter diesem Namen.`);}catch(e){libraryStatus(e.message,true);}};
 $('#grammar-import').onchange=async event=>{const input=event.target;try{const file=input.files[0];if(!file)return;if(file.size>200000)throw Error('Die Grammatikdatei ist zu gross (maximal 200 KB).');const entry=importGrammar(await file.text()),entries=library(),originalName=entry.name;entry.name=unusedImportName(entries,entry.name);writeLibrary(putGrammar(entries,entry),entry.name);libraryStatus(`„${entry.name}“ importiert${entry.name!==originalName?' – mit Namenszusatz, damit der vorhandene Eintrag erhalten bleibt':''}. Wähle „Gespeicherte Grammatik laden“, um sie zu bearbeiten. Der aktuelle Editorinhalt bleibt unverändert.`);}catch(e){libraryStatus(e.message,true);}finally{input.value='';}};
 const report=g=>`${g.rules.size} Bausteine geprüft. ${g.warnings.length?g.warnings.join(' '):'Alle Bausteine sind erreichbar und können in fertigen Text übergehen.'}`;
 $('#grammar-check').onclick=()=>{try{status(report(compile()));}catch(e){status(e.message,true);}};
 $('#grammar-generate').onclick=()=>{try{const grammar=compile(),result=generateFromGrammar(grammar,Number($('#grammar-count').value));state.notes.generated=result.text;state.notes['grammar-trace']=result.trace;save();$('#generated').textContent=result.text;$('#grammar-trace').textContent=result.trace;status(report(grammar)+' Neue Verse erzeugt.');}catch(e){status(e.message+' Die letzte Ausgabe bleibt erhalten.',true);}};
 for(const id of ['grammar-rules','grammar-words','grammar-start','grammar-count'])$('#'+id).addEventListener('input',()=>status('Editor geändert. Prüfe die Regeln oder erzeuge neue Verse; die letzte Ausgabe bleibt zum Vergleichen stehen.'));
 $('#take-generated').onclick=()=>{if(!state.notes.generated)return toast('Erzeuge zuerst Verse.');modal('<h2>Arbeitsfassung übernehmen?</h2><p>Die bisherige Arbeitsfassung bleibt im Sicherungsfeld erhalten. Die erzeugten Verse kannst du anschliessend frei verändern.</p><button class="primary" id="confirm-take">Verse übernehmen</button>');$('#confirm-take').onclick=()=>{state.notes.previous=state.notes.poem||'';state.notes.poem=state.notes.generated;save();$('#dialog').close();work('buehne');};};
 $('#grammar-download').onclick=()=>{persistEditor();download('meine-d-gram-regeln.txt',`REGELN\n${$('#grammar-rules').value}\n\nWORTFELDER\n${$('#grammar-words').value}\n\nSTARTSYMBOL: ${$('#grammar-start').value}\nANZAHL VERSE: ${$('#grammar-count').value}\n\nEigenes Regelmaterial aus Zwischen den Zeilen.\nWerkzeugprinzip: DILAITS / D-Gram, ${dilaits}\n`);};
 const exampleSelect=$('#grammar-example-select');
 const showExample=()=>{const example=GRAMMAR_EXAMPLES.find(item=>item.id===exampleSelect.value);const reel=REEL_WRITING_PROMPTS.find(item=>item.id===state.notes['grammar-reel-id']&&item.example===example.id);$('#grammar-example-info').innerHTML=`<p class="eyebrow">${esc(example.category)}</p><h3>${esc(example.title)}</h3><p>${esc(example.description)}</p><h3>Dein Arbeitsauftrag</h3><p>${esc(example.task)}</p>${reel?`<aside class="card"><p class="eyebrow">WÖRTER AUSPROBIEREN</p><h3>${esc(reel.title)}</h3><p>${esc(reel.grammarTask)}</p><p class="small">Mit „Beispiel in den Editor laden“ beginnst du. Dein bisheriger Bauplan bleibt bis dahin erhalten und wird beim Laden zur Wiederherstellung zwischengespeichert.</p></aside>`:''}`;state.notes['grammar-example-selected']=example.id;save();};
 showExample();exampleSelect.onchange=showExample;
 $('#grammar-load-example').onclick=()=>{const example=GRAMMAR_EXAMPLES.find(item=>item.id===exampleSelect.value);persistEditor();for(const key of ['rules','words','start','count'])state.notes['grammar-previous-'+key]=state.notes['grammar-'+key];state.notes['grammar-rules']=example.rules;state.notes['grammar-words']=example.words;state.notes['grammar-start']=example.start;state.notes['grammar-count']=String(example.count);state.notes['grammar-example-loaded']=example.id;save();work('baukasten');status(`Beispiel „${example.title}“ geladen. Ändere die Wortfelder oder erzeuge eine erste Fassung.`);};
 $('#grammar-undo-example').onclick=()=>{for(const key of ['rules','words','start','count']){state.notes['grammar-'+key]=state.notes['grammar-previous-'+key];delete state.notes['grammar-previous-'+key];}delete state.notes['grammar-example-loaded'];save();work('baukasten');status('Vorheriger Bauplan wiederhergestellt. Deine letzte Versausgabe bleibt unverändert.');};
}
function favoriteIds(){try{const value=JSON.parse(state.notes['inspiration-favorites']||'[]');return Array.isArray(value)?value.filter(id=>inspirationItems.some(item=>item.id===id)):[];}catch{return [];}}
function inspiration(){return `<div class="topline"><span>DEINE INSPIRATIONSBIBLIOTHEK</span><span class="pill">${POEMS.length} TEXTE · ${MEDIA.length} MEDIENQUELLEN</span></div><div class="station-head"><h1>Claras Worte.<br><em>Deine Gedanken.</em></h1><p class="intro">Clara Lösel als Lyrikerin und literarische Content Creatorin: Gedichte, Reels, Gespräche. Lies und höre zu. Was möchtest du selbst schreiben?</p></div>${reelGallery()}<div class="inspiration-intro"><p><strong>Gedicht, Vortrag, Selbstbeschreibung:</strong> Das sind verschiedene Zugänge. Die Textdeutungen und Arbeitsaufträge hier sind Angebote dieser Unterrichtseinheit, keine Aussagen der Autorin.</p><p class="small">Buchgrundlage: <cite>Wehe du gibst auf</cite>, bereitgestellte PDF, 18. Auflage 2026. Die Karten kennzeichnen kurze Volltexte und Auszüge. Die genannten Seiten sind PDF-Dateiseiten. Geprüfte Medienquellen: 27.11.2026. Verfügbarkeit und Anmeldung können sich ändern.</p></div><div class="tabs" role="group" aria-label="Inspiration auswählen">${['Alle','Gedichte','Filme','Podcasts','Porträts','Poetologie'].map(type=>`<button data-inspiration-type="${type}" aria-pressed="${inspirationFilter.type===type}">${type}</button>`).join('')}</div><div class="inspiration-filters"><div><label class="field" for="inspiration-search">Titel, Thema oder Verfahren suchen</label><input type="search" id="inspiration-search" value="${esc(inspirationFilter.query)}" placeholder="z. B. Anapher, Hoffnung, Stimme"></div><div><label class="field" for="inspiration-theme">Thema</label><select id="inspiration-theme">${['Alle','Liebe','Nähe','Selbstwert','Gesellschaft','Hoffnung','Schreiben','Poetologie'].map(theme=>`<option ${theme===inspirationFilter.theme?'selected':''}>${theme}</option>`).join('')}</select></div><label class="favorite-filter"><input type="checkbox" id="inspiration-favorites" ${inspirationFilter.favoritesOnly?'checked':''}> Nur meine Merkliste</label></div><p id="inspiration-count" class="small" role="status"></p><div id="inspiration-results"></div><details class="local-book"><summary>Das eigene Buch-PDF direkt hier lesen</summary><p class="small">Wähle deine rechtmässig verfügbare PDF-Datei. Sie wird ausschliesslich in diesem Tab geöffnet, nicht hochgeladen oder mitgesichert. Ohne Datei zeigen die Karten weiterhin ihre Textauszüge. Beim Schliessen des Tabs wird das lokale Buch wieder geschlossen.</p><label class="field" for="inspiration-book">Eigenes Buch-PDF auswählen</label><input id="inspiration-book" type="file" accept="application/pdf,.pdf"><p id="book-status" class="small">${bookURL?'Dein lokales Buch ist für die Textkarten geöffnet.':'Noch kein lokales Buch geöffnet.'}</p><div id="book-view"></div></details><article class="card inspiration-home"><h2>Die Wege zu den Originalen</h2><p>Die offizielle Website verlinkt die Social-Media-Kanäle. Auf ihrer geprüften Startseite ist kein eigener Film eingebunden. Konkrete Original-Reels und Verlags-/Senderfilme findest du oben bei „Filme“.</p><div class="actions"><a href="https://claraloesel.de/" target="_blank" rel="noopener noreferrer">Offizielle Website</a><a href="https://www.youtube.com/@claraloesel" target="_blank" rel="noopener noreferrer">Offizieller YouTube-Kanal</a><a href="https://www.instagram.com/claraloesel/" target="_blank" rel="noopener noreferrer">Instagram</a><a href="https://www.tiktok.com/@claraloesel" target="_blank" rel="noopener noreferrer">TikTok</a></div></article>${field('inspiration-notes','Dein Inspirationsjournal: Quelle → Beobachtung → eigene Idee','Notiere Titel, Seite oder Zeitstelle. Was willst du ausprobieren – und was bewusst anders machen?')}`;}
function bindInspiration(){
 document.querySelectorAll('[data-inspiration-type]').forEach(button=>button.onclick=()=>{inspirationFilter.type=button.dataset.inspirationType;document.querySelectorAll('[data-inspiration-type]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));drawInspiration();});
 $('#inspiration-search').oninput=event=>{inspirationFilter.query=event.target.value;drawInspiration();};$('#inspiration-theme').onchange=event=>{inspirationFilter.theme=event.target.value;drawInspiration();};$('#inspiration-favorites').onchange=event=>{inspirationFilter.favoritesOnly=event.target.checked;drawInspiration();};
 $('#inspiration-book').onchange=event=>{const file=event.target.files[0];if(!file)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf'))return toast('Bitte eine PDF-Datei auswählen.');if(bookURL)URL.revokeObjectURL(bookURL);bookURL=URL.createObjectURL(file);$('#book-status').textContent='Lokales Buch geöffnet. Über „Im eigenen PDF lesen“ in einer Textkarte springst du zur Dateiseite.';$('#book-view').innerHTML=`<iframe class="book-frame" title="Dein lokal geöffnetes Buch" src="pdf-viewer.html?file=${encodeURIComponent(bookURL)}&amp;page=15"></iframe>`;};drawInspiration();
}
function drawInspiration(){
 const results=$('#inspiration-results'),favorites=favoriteIds();
 if(inspirationFilter.type==='Poetologie'){
 const concepts=POETOLOGY.filter(concept=>{const linked=inspirationItems.filter(item=>[...concept.sourceIds,...concept.poemIds].includes(item.id));const text=[concept.title,concept.question,concept.task,...linked.map(item=>item.title)].join(' ').toLocaleLowerCase('de');return (!inspirationFilter.query.trim()||text.includes(inspirationFilter.query.trim().toLocaleLowerCase('de')))&&(inspirationFilter.theme==='Alle'||linked.some(item=>(item.themes||[item.theme]).includes(inspirationFilter.theme)))&&(!inspirationFilter.favoritesOnly||linked.some(item=>favorites.includes(item.id)));});$('#inspiration-count').textContent=`${concepts.length} Wege, über das Schreiben nachzudenken`;results.innerHTML=`<article class="card poetology-lead"><h2>Poetologie: Was sagt Literatur über ihr eigenes Machen?</h2><p>Frage nach Herkunft, Form, Publikum und Wirkung von Texten. Unterscheide das, was eine Autorin im Interview sagt, von deiner Deutung eines Gedichts. Ein Gespräch liefert eine Perspektive, keinen endgültigen Schlüssel.</p></article><div class="inspiration-grid">${concepts.map(concept=>`<article class="resource-card"><p class="eyebrow">FRAGE AN DAS SCHREIBEN</p><h2>${esc(concept.title)}</h2><p>${esc(concept.question)}</p><h3>Gegenlesen und gegenhören</h3><div class="source-chips">${[...concept.sourceIds,...concept.poemIds].map(id=>{const resource=inspirationItems.find(item=>item.id===id);return `<button data-resource="${id}">${esc(resource.title)}</button>`;}).join('')}</div><h3>Dein Versuch</h3><p>${esc(concept.task)}</p></article>`).join('')}</div>`;
 }else{
 const items=filterResources(inspirationItems,{...inspirationFilter,favorites});$('#inspiration-count').textContent=`${items.length} Fundstücke${inspirationFilter.favoritesOnly?' in deiner Merkliste':''}`;
 results.innerHTML=items.length?`<div class="inspiration-grid">${items.map(item=>`<article class="resource-card"><div class="resource-meta"><span>${item.type==='Gedichte'?'CLARA LÖSEL · TEXT':esc(item.type.toUpperCase())}</span><button data-favorite="${item.id}" aria-pressed="${favorites.includes(item.id)}" aria-label="${favorites.includes(item.id)?'Aus Merkliste entfernen':'Merken'}: ${esc(item.title)}">${favorites.includes(item.id)?'★':'☆'}</button></div><h2>${esc(item.title)}</h2><p class="small">${esc(item.type==='Gedichte'?`${item.form} · PDF-Seite ${item.page}`:item.publisher)}</p>${item.sensitive?`<p class="content-note">Themenhinweis: ${esc(item.sensitive)}</p>`:''}${item.type==='Gedichte'?`<p class="resource-teaser">${esc(item.reading)}</p>`:`<p>${esc(item.note)}</p>`}<div class="source-chips">${(item.themes||[item.theme]).map(theme=>`<span class="pill">${esc(theme)}</span>`).join('')}</div><button class="resource-open" data-resource="${item.id}">${item.type==='Gedichte'?'Text & Schreibimpuls öffnen':'Quelle & Hör-/Sehauftrag öffnen'}</button></article>`).join('')}</div>`:'<div class="feedback">Keine passenden Fundstücke. Ändere die Suche oder den Themenfilter. Du merkst Quellen mit dem Stern auf ihrer Karte vor.</div>';
 }
 results.querySelectorAll('[data-resource]').forEach(button=>button.onclick=()=>openResource(button.dataset.resource));results.querySelectorAll('[data-favorite]').forEach(button=>button.onclick=()=>toggleFavorite(button.dataset.favorite));
}
function toggleFavorite(id){let favorites=favoriteIds();favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];state.notes['inspiration-favorites']=JSON.stringify(favorites);save();if(route==='inspiration')drawInspiration();return favorites.includes(id);}
function openResource(id){
 const item=inspirationItems.find(resource=>resource.id===id);if(!item)return;
 modal(`<p class="eyebrow">${item.type==='Gedichte'?'CLARA LÖSEL · WEHE DU GIBST AUF':esc(item.type.toUpperCase())}</p><h2>${esc(item.title)}</h2>${item.sensitive?`<p class="content-note">Themenhinweis: ${esc(item.sensitive)}. Du kannst diese Quelle jederzeit schliessen oder eine andere auswählen.</p>`:''}${item.type==='Gedichte'?`<p class="small">${esc(item.extent)} · ${item.number?`${item.number}/101 · `:''}PDF-Dateiseite ${item.page}</p><blockquote class="resource-poem">${esc(item.text)}</blockquote><p class="poem-meta">Clara Lösel: <cite>Wehe du gibst auf</cite>. NOW, bereitgestellte PDF, 18. Auflage 2026. Rechte bei der Autorin / dem Verlag. Zeilenfolge nach der Datei.</p><h3>Ein möglicher Zugang</h3><p>${esc(item.reading)}</p><button id="resource-book">Im eigenen PDF lesen · Seite ${item.page}</button>`:`<p class="small">${esc(item.publisher)}</p><p>${esc(item.note)}</p><div class="actions"><a class="primary" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Originalquelle öffnen</a>${item.youtube||item.instagram||item.audio?'<button id="resource-player">Medium hier laden</button>':''}</div><div id="resource-player-area"></div><p class="small">Externe Medien werden erst nach „Medium hier laden“ aufgerufen. Dabei erhält der Anbieter unter anderem deine IP-Adresse; Plattformen können eine Anmeldung oder Cookies verlangen. Einbettungen können gesperrt sein – nutze dann die Originalquelle. Kein automatisches Abspielen.</p>`}<h3>${item.type==='Gedichte'?'Dein Schreibversuch':'Dein Hör-/Seh-/Leseauftrag'}</h3><p>${esc(item.task)}</p><div class="actions"><button class="primary" id="resource-write">Mit diesem Impuls schreiben</button>${item.example?'<button id="resource-example">Passenden Bauplan in der Werkstatt auswählen</button>':''}<button id="resource-favorite" aria-pressed="${favoriteIds().includes(id)}">${favoriteIds().includes(id)?'★ Gemerkt':'☆ Quelle merken'}</button></div>${item.related?.length?`<h3>Dazu hören, sehen, weiterlesen</h3><div class="source-chips">${item.related.map(relatedId=>{const related=MEDIA.find(media=>media.id===relatedId);return `<button data-related="${relatedId}">${esc(related.title)}</button>`;}).join('')}</div>`:''}${field('resource-note-'+id,'Deine Notiz zu dieser Quelle','Beleg, Zeitstelle, Bild oder eigene Idee …')}`);
 $('#resource-write').onclick=()=>{state.notes['inspiration-impuls']=`${item.title} (${item.type==='Gedichte'?'PDF-Seite '+item.page:item.url})\n${item.task}`;save();$('#dialog').close();pendingWork='impuls';location.hash='werkstatt';};
 $('#resource-example')?.addEventListener('click',()=>{delete state.notes['grammar-reel-id'];state.notes['grammar-example-selected']=item.example;state.notes['inspiration-impuls']=`${item.title}: ${item.task}`;save();$('#dialog').close();pendingWork='baukasten';location.hash='werkstatt';});
 $('#resource-favorite').onclick=()=>{const selected=toggleFavorite(id);$('#resource-favorite').textContent=selected?'★ Gemerkt':'☆ Quelle merken';$('#resource-favorite').setAttribute('aria-pressed',String(selected));};
 $('#resource-book')?.addEventListener('click',()=>{if(!bookURL){$('#dialog').close();$('.local-book').open=true;$('#inspiration-book').focus();toast('Wähle zuerst dein eigenes Buch-PDF. Es bleibt lokal in diesem Tab.');return;}$('#dialog-content').innerHTML=`<h2>${esc(item.title)} · PDF-Seite ${item.page}</h2><iframe class="book-frame" title="${esc(item.title)} im lokalen Buch" src="pdf-viewer.html?file=${encodeURIComponent(bookURL)}&amp;page=${item.page}"></iframe><button id="back-resource">Zur Textkarte zurück</button>`;$('#back-resource').onclick=()=>{openResource(id);};});
 $('#resource-player')?.addEventListener('click',()=>{const area=$('#resource-player-area');if(item.audio){area.innerHTML=`<audio controls preload="none" src="${esc(item.audio)}">Bitte öffne die Originalquelle.</audio>`;}else{const src=item.youtube?`https://www.youtube-nocookie.com/embed/${item.youtube}`:`https://www.instagram.com/p/${item.instagram}/embed/`;area.innerHTML=`<iframe class="media-frame" title="${esc(item.title)}" src="${src}" allow="encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;}$('#resource-player').disabled=true;});
 document.querySelectorAll('[data-related]').forEach(button=>button.onclick=()=>openResource(button.dataset.related));$('#dialog-content').querySelectorAll('[data-save]').forEach(input=>input.oninput=()=>{state.notes[input.dataset.save]=input.value;save();});
}

function bindWordFieldEditor(persistEditor,status){
 const source=$('#grammar-words'),forms=$('#wordfield-forms'),feedback=$('#wordfield-status');
 const tell=message=>{feedback.textContent=message;};
 const renderFields=()=>{
  try{
   const fields=readWordFields(source.value);
   forms.innerHTML=fields.length?fields.map(field=>field.values?`<fieldset class="wordfield-group" data-wordfield="${field.index}"><legend>${esc(field.name)}</legend><div class="actions wordfield-manage"><button type="button" data-wordfield-rename aria-label="Wortfeld ${esc(field.name)} umbenennen">Umbenennen</button><button type="button" data-wordfield-delete aria-label="Wortfeld ${esc(field.name)} löschen">Wortfeld löschen</button></div>${field.values.map((value,i)=>`<div class="wordfield-row"><label class="sr-only" for="word-${field.index}-${i}">${esc(field.name)} · Eintrag ${i+1}</label><textarea id="word-${field.index}-${i}" data-word-index="${i}" rows="2" placeholder="Dein Wort oder deine Wendung …">${esc(value)}</textarea><button data-word-remove="${i}" aria-label="Eintrag ${i+1} aus ${esc(field.name)} entfernen" ${field.values.length===1?'disabled':''}>Entfernen</button></div>`).join('')}<button data-word-add aria-label="Eintrag zu ${esc(field.name)} hinzufügen">Eintrag hinzufügen</button><p class="small">${field.values.length} ${field.values.length===1?'Eintrag':'Einträge'} · Mindestens ein Eintrag bleibt im Wortfeld.</p></fieldset>`:`<aside class="card"><h3>${esc(field.name)}</h3><p class="small">Dieses Feld enthält eine unvollständige oder zusammengesetzte Regel. Du kannst es unter „Wortfelder als Text bearbeiten“ ändern; der Text bleibt erhalten.</p><p class="small">${esc(field.error)}</p></aside>`).join(''):'<p class="small">Noch keine Wortfelder vorhanden. Lege oben dein erstes Wortfeld an oder lade ein Beispiel.</p>';
   forms.querySelectorAll('[data-wordfield]').forEach(group=>{
    const line=Number(group.dataset.wordfield);
    const change=(edit,redraw=false,focusIndex=0)=>{
     try{
      const field=readWordFields(source.value).find(field=>field.index===line),values=[...field.values];edit(values);
      source.value=updateWordField(source.value,line,values);persistEditor();status('Wortfelder geändert. Erzeuge neue Verse, um sie auszuprobieren.');tell(`„${field.name}“ gespeichert. Die letzte Versausgabe bleibt zum Vergleichen stehen.`);
      if(redraw){renderFields();$(`#word-${line}-${focusIndex}`)?.focus();}
     }catch(error){tell(error.message);}
    };
    group.querySelectorAll('[data-word-index]').forEach(input=>input.oninput=()=>change(values=>{values[Number(input.dataset.wordIndex)]=input.value;}));
    group.querySelectorAll('[data-word-remove]').forEach(button=>button.onclick=()=>{const index=Number(button.dataset.wordRemove);change(values=>values.splice(index,1),true,Math.max(0,index-1));});
    group.querySelector('[data-word-add]').onclick=()=>{const field=readWordFields(source.value).find(field=>field.index===line);change(values=>values.push(''),true,field.values.length);};
    const applyStructure=result=>{
     persistEditor();for(const key of ['rules','words','start','count'])state.notes['grammar-previous-'+key]=state.notes['grammar-'+key];
     $('#grammar-rules').value=result.rules;source.value=result.words;$('#grammar-start').value=result.start;
     persistEditor();renderFields();$('#grammar-undo-example').disabled=false;$('#dialog').close();
    };
    group.querySelector('[data-wordfield-rename]').onclick=()=>{
     const field=readWordFields(source.value).find(field=>field.index===line);
     modal(`<h2>Wortfeld umbenennen</h2><p>Verweise in Regeln und Wortfeldern sowie das Startsymbol werden automatisch angepasst. Wörter, Wendungen und Kommentare bleiben unverändert.</p><form id="wordfield-rename-form"><label class="field" for="wordfield-rename-name">Neuer Name</label><input id="wordfield-rename-name" type="text" maxlength="60" value="${esc(field.name)}"><p class="small">Leerzeichen werden zu Unterstrichen. Ein bereits vergebener Name bleibt geschützt.</p><p id="wordfield-rename-feedback" role="status" aria-live="polite"></p><button type="submit" class="primary">Name speichern</button></form>`);
     $('#wordfield-rename-name').focus();
     $('#wordfield-rename-form').onsubmit=event=>{
      event.preventDefault();
      try{
       const result=renameWordField($('#grammar-rules').value,source.value,$('#grammar-start').value,line,$('#wordfield-rename-name').value);
       applyStructure(result);tell(`„${field.name}“ heisst jetzt „${result.name}“. Alle Verweise sind angepasst. Mit „Vorherigen Bauplan wiederherstellen“ kannst du die Änderung zurücknehmen.`);status('Wortfeld umbenannt und Verweise angepasst. Die letzte Ausgabe bleibt erhalten.');
       $(`#word-${line}-0`)?.focus();
      }catch(error){$('#wordfield-rename-feedback').textContent=error.message;}
     };
    };
    group.querySelector('[data-wordfield-delete]').onclick=()=>{
     const usage=wordFieldUsage($('#grammar-rules').value,source.value,$('#grammar-start').value,line);
     const alternatives=readWordFields(source.value).filter(field=>field.values&&field.name!==usage.name);
     modal(`<h2>Wortfeld „${esc(usage.name)}“ löschen?</h2><p>${usage.used?'Dieses Wortfeld wird noch verwendet. Wähle ein anderes Feld; die Verweise und gegebenenfalls das Startsymbol werden automatisch darauf umgestellt.':'Dieses Wortfeld wird in den aktuellen Regeln und im Startsymbol nicht verwendet. Seine Einträge werden aus dem Editor entfernt.'}</p>${usage.used?alternatives.length?`<label class="field" for="wordfield-delete-replacement">Verweise ersetzen durch</label><select id="wordfield-delete-replacement"><option value="">Anderes Wortfeld wählen …</option>${[...new Set(alternatives.map(field=>field.name))].map(name=>`<option value="${esc(name)}">${esc(name)}</option>`).join('')}</select>`:'<p>Lege zuerst ein anderes Wortfeld an, das die Verweise übernehmen kann.</p>':''}<p class="small">Über „Vorherigen Bauplan wiederherstellen“ kannst du die Löschung zurücknehmen. Gespeicherte Grammatiken in deiner Bibliothek behalten ihren bisherigen Stand.</p><p id="wordfield-delete-feedback" role="status" aria-live="polite"></p><div class="actions"><button id="wordfield-cancel-delete">Abbrechen</button><button class="primary" id="wordfield-confirm-delete" ${usage.used&&!alternatives.length?'disabled':''}>Wortfeld löschen</button></div>`);
     $('#wordfield-cancel-delete').onclick=()=>$('#dialog').close();
     $('#wordfield-confirm-delete').onclick=()=>{
      try{
       const replacement=$('#wordfield-delete-replacement')?.value||'';
       const result=deleteWordField($('#grammar-rules').value,source.value,$('#grammar-start').value,line,replacement);
       applyStructure(result);tell(`„${usage.name}“ gelöscht.${replacement?` Die Verweise verwenden jetzt „${replacement}“.`:''} Die Änderung kann über „Vorherigen Bauplan wiederherstellen“ zurückgenommen werden.`);status('Wortfeld gelöscht. Die letzte Versausgabe bleibt erhalten.');$('#wordfield-name').focus();
      }catch(error){$('#wordfield-delete-feedback').textContent=error.message;}
     };
    };
   });
  }catch(error){forms.textContent=error.message;}
 };
 $('#wordfield-create').onsubmit=event=>{
  event.preventDefault();
  try{
   const values=$('#wordfield-first-entries').value.split(/\r?\n/).map(value=>value.trim()).filter(Boolean);
   const field=createWordField($('#grammar-rules').value,source.value,$('#wordfield-name').value,values);
   source.value=field.words;
   const useNew=$('#wordfield-use-new').checked;
   if(useNew)$('#grammar-start').value=field.name;
   persistEditor();renderFields();
   $('#wordfield-name').value='';$('#wordfield-first-entries').value='';$('#wordfield-use-new').checked=false;
   tell(`„${field.name}“ angelegt und gespeichert. ${useNew?'Klicke auf „Verse erzeugen“, um die neuen Einträge auszuprobieren.':'Das Feld ist zum Sammeln bereit. Verwende seinen Namen in einer Regel oder als Startsymbol, wenn es in der Ausgabe erscheinen soll.'}`);
   status(useNew?`„${field.name}“ ist jetzt das Startsymbol. Erzeuge neue Verse.`:'Neues Wortfeld gespeichert. Die bisherigen Regeln und die letzte Ausgabe bleiben erhalten.');
   $(`#word-${field.index}-0`)?.focus();
  }catch(error){tell(error.message);}
 };
 source.addEventListener('input',()=>{renderFields();tell('Eingabefelder aus der Textansicht aktualisiert.');});
 renderFields();
}
